mapper.select:
select su.user_id as userId, su.user_name as userName, su.nike_name as nikeName, coalesce(nullif(sr.display_name, ''), sr.role_name) as specialRole from sys_user su left join sys_user_role sur on sur.user_id = su.user_id left join sys_role sr on sr.role_id = sur.role_id and sr.special_role = 1 and sr.status = 0 and sr.del_flag = 0 where su.del_flag = 0 and su.user_id in
#{userId}
order by su.user_id asc, sr.role_id asc
